import { db } from '@neerkaavalan/database';
import { DeviceGatewayService } from './index.js';
import { createDeviceAdapter } from './adapterFactory.js';
async function main() {
    console.log('');
    console.log('========================================');
    console.log(' DEVICE ADAPTER FACTORY TEST');
    console.log('========================================');
    console.log('');
    console.log('[1] Reading operating mode from database...');
    const adapter = await createDeviceAdapter('NK-U01');
    console.log('');
    console.log('Adapter selected:');
    console.log(`  Device : ${adapter.deviceCode}`);
    console.log(`  Type   : ${adapter.deviceType}`);
    console.log(`  Mode   : ${adapter.operatingMode}`);
    console.log('');
    console.log('[2] Registering adapter with gateway...');
    const gateway = new DeviceGatewayService();
    gateway.registerAdapter(adapter);
    console.log('Adapter registered successfully.');
    console.log('');
    console.log('[3] Connecting through gateway...');
    const state = await gateway.connectDevice('NK-U01');
    console.log('');
    console.log('Gateway State:');
    console.log(JSON.stringify(state, null, 2));
    console.log('');
    console.log('========================================');
    console.log(' ADAPTER FACTORY TEST PASSED');
    console.log('========================================');
    console.log('');
    await db.end();
}
main().catch(async (error) => {
    console.error('');
    console.error('========================================');
    console.error(' ADAPTER FACTORY TEST FAILED');
    console.error('========================================');
    console.error('');
    console.error(error);
    await db.end();
    process.exit(1);
});
